import{_ as o,C as t,o as s,c as r,E as n,a2 as c}from"./chunks/framework.BOeh4kYD.js";const d="/joinwell52/assets/principal-receipt-20260908/01-source-projection.en.svg",y=JSON.parse(`{"title":"Same Agent, Different Person: Whose Permissions Should the Next Action Use?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Same Agent, Different Person: Whose Permissions Should the Next Action Use?","date":"2026-09-08","published_date":"2026-09-08","column":"open-source-engineering","category":"daily","article_type":"comparative-engineering-analysis","edition":"research-center","research_question":"Same Agent, Different Person: Whose Permissions Should the Next Action Use?","summary":"A shared agent's execution identity, instruction reference, responsible person and operation authority are different layers. Existing actor checks held in our probes, while a narrower continuation-to-session projection gap emerged.","cover":"/assets/principal-receipt-20260908/01-shared-identity-cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded research complete; public record checks; not independent QA; no development authorized","source_commit":"c008d9db91a21136fc61a4f60314e22db395d5d2","pageClass":"principal-receipt-article","sources":["https://github.com/paperclipai/paperclip/pull/13005"]},"headers":[],"relativePath":"en/engineering/2026-09-08-shared-agent-instruction-identity.md","filePath":"en/engineering/2026-09-08-shared-agent-instruction-identity.md","lastUpdated":1788849182000}`),l={name:"en/engineering/2026-09-08-shared-agent-instruction-identity.md"};function h(p,e,u,m,g,b){const a=t("ArticleCover"),i=t("ArticleTableScroll");return s(),r("div",null,[n(a,{image:"/assets/principal-receipt-20260908/01-shared-identity-cover-v1.png",kicker:"Open-source engineering · Controlled research",title:"Same Agent, Different Person: Whose Permissions Should the Next Action Use?",summary:"A shared agent's execution identity, instruction reference, responsible person and operation authority are different layers. Existing actor checks held in our probes, while a narrower continuation-to-session projection gap emerged.",version:"2026-09-08",languageHref:"/zh/engineering/2026-09-08-shared-agent-instruction-identity",languageLabel:"简体中文"}),n(i,{language:"en"}),e[0]||(e[0]=c(`<p><a href="https://joinwell52-ai.github.io/joinwell52/assets/principal-receipt-20260908/01-shared-identity-cover-v1.png" target="_blank" rel="noreferrer">Full-resolution cover</a></p><h1 id="same-agent-different-person-whose-permissions-should-the-next-action-use" tabindex="-1">Same Agent, Different Person: Whose Permissions Should the Next Action Use? <a class="header-anchor" href="#same-agent-different-person-whose-permissions-should-the-next-action-use" aria-label="Permalink to &quot;Same Agent, Different Person: Whose Permissions Should the Next Action Use?&quot;">​</a></h1><p>A digital employee handles code for Alice, then accepts a new instruction from Bob. The conversation continues, the task is unchanged, and the same agent does the work.</p><p>Whose permissions should it use for its next repository operation?</p><p>This is an illustrative situation, not an account incident we discovered. It sounds like switching a login, but it involves another timeline: Alice&#39;s action might already have started, Bob&#39;s instruction has just been accepted, and previously queued work may still belong to Alice.</p><p>Always following the latest speaker could reassign an older instruction to the wrong person. Always retaining the credentials from agent startup could let a new instruction continue using the previous person&#39;s access.</p><p><strong>A session can continue without making responsibility and authority automatically continuous.</strong></p><h2 id="_1-paperclip-changes-operation-time-identity-not-just-chat-identity" tabindex="-1">1. Paperclip changes operation-time identity, not just chat identity <a class="header-anchor" href="#_1-paperclip-changes-operation-time-identity-not-just-chat-identity" aria-label="Permalink to &quot;1. Paperclip changes operation-time identity, not just chat identity&quot;">​</a></h2><p>Paperclip is an open-source application for organizing and managing AI agent work. Its concrete problem is that several people can instruct the same agent on the same task. The task assignee is not necessarily the person responsible for the instruction behind the current action.</p><p>A change merged on September 7, 2026 separates task ownership from execution identity and selects credentials when a managed GitHub operation begins. An action that has already started retains its captured identity. A retry without a new instruction must not switch identity merely because someone spoke later. The author reports switching tests involving two users and two GitHub accounts; we did not rerun those account tests. <a href="https://github.com/paperclipai/paperclip/pull/13005" target="_blank" rel="noreferrer">Paperclip #13005</a></p><p>The boundary matters: this concerns credential selection for managed operations. It does not promise isolation from arbitrary code deliberately copying credentials within the same execution principal. <a href="https://github.com/paperclipai/paperclip/pull/13005" target="_blank" rel="noreferrer">Risk statement</a></p><p>What is worth learning first is not the component count, but the separation of four questions:</p><table tabindex="0"><thead><tr><th>Question</th><th>Identity or evidence needed</th></tr></thead><tbody><tr><td>Who executes the work?</td><td>The agent&#39;s execution identity</td></tr><tr><td>Which instruction caused this action?</td><td>A reference to the accepted instruction</td></tr><tr><td>Who is responsible for that instruction?</td><td>An authenticated, policy-resolved person</td></tr><tr><td>What access may this action actually use?</td><td>Credentials and authority checked at the action boundary</td></tr></tbody></table><p>These can be connected, but similar names do not make them interchangeable. A developer role describes a responsibility, not which colleague issued an instruction. A message originating from Alice does not automatically establish Alice&#39;s authority to request its contents.</p><h2 id="_2-does-our-own-system-actually-have-the-same-problem" tabindex="-1">2. Does our own system actually have the same problem? <a class="header-anchor" href="#_2-does-our-own-system-actually-have-the-same-problem" aria-label="Permalink to &quot;2. Does our own system actually have the same problem?&quot;">​</a></h2><p>CodeFlowMu is our locally running multi-agent collaboration system. FCoP task, report and review records organize its work. The runtime handles sessions and technical execution without replacing management roles&#39; business decisions.</p><p>It would be easy to see an external project&#39;s shared-identity feature and announce that we need the same feature. That skips the important question: what does our own evidence establish?</p><p>We inspected selected local records on September 8. The records themselves were from September 5, not new incidents that day.</p><table tabindex="0"><thead><tr><th>Selected data</th><th>Actual unit</th><th>What it tells us</th></tr></thead><tbody><tr><td>Operation approvals</td><td>1 approval record</td><td>The deciding role was ADMIN; this cannot estimate authenticated-person coverage</td></tr><tr><td>Task-command receipts</td><td>10 rows for 5 idempotency keys</td><td>Each key has processing and completed events; these are not 10 independent tasks</td></tr><tr><td>Skill invocations</td><td>25 rows and 25 invocation IDs</td><td>9 have nonempty session IDs; the remainder must be distinguished from legitimate sessionless work before judging them</td></tr></tbody></table><p>No malformed rows appeared in this selection. Several explicitly named human-identity, instruction-responsibility and credential-grant fields were absent, but this describes the selected fields and records only. Other modules may hold equivalent information.</p><p>The history therefore does not support a claim that cross-person credential misuse occurred. Its useful message is narrower: <strong>records describing operations, commands, roles and invocations cannot simply be read as an authenticated human responsibility chain.</strong></p><p>The next question is not where to add a person&#39;s name, but whose identity the current request already binds.</p><h2 id="_3-a-different-agent-does-not-automatically-inherit-an-old-approval" tabindex="-1">3. A different agent does not automatically inherit an old approval <a class="header-anchor" href="#_3-a-different-agent-does-not-automatically-inherit-an-old-approval" aria-label="Permalink to &quot;3. A different agent does not automatically inherit an old approval&quot;">​</a></h2><p>We called the actual operation approval service and saved its real record format. After approval checks pass, the service invokes a function to do the work: the execution callback. In this experiment, that function only counted calls instead of performing an operation. No repository was connected.</p><p>A request digest is an operation-identity check: changing protected request contents should prevent an old approval from being used as though the request were unchanged.</p><table tabindex="0"><thead><tr><th>Control</th><th>Observation</th><th>Supported interpretation</th></tr></thead><tbody><tr><td>Check and execute the original request</td><td>1 callback</td><td>The basic allowed path works</td></tr><tr><td>Change only the subject from one agent to another</td><td>Digest changes; <code>APPROVAL_STALE</code>; 0 callbacks</td><td>An old approval cannot directly be used for another request subject</td></tr><tr><td>Change only the session ID</td><td>Same digest; 1 callback</td><td>This digest excludes session identity; this does not authorize an entire takeover workflow</td></tr><tr><td>Reuse a task-command key but change its submitting actor</td><td><code>idempotency_key_conflict</code>; no second callback</td><td>The command layer also checks actor differences</td></tr></tbody></table><p>The second round also called the real operation-policy builder instead of constructing the request entirely in research code. It derived <code>subject.actor</code> from <code>agentId</code>. Changing the agent changed the digest of the actual constructed request.</p><p>The protection exists. It answers which agent submitted the operation, not which authenticated human is responsible for it. Those questions need a connection; one field does not inherently answer both.</p><h2 id="_4-the-reproduced-gap-is-much-narrower-than-an-incomplete-identity-system" tabindex="-1">4. The reproduced gap is much narrower than an incomplete identity system <a class="header-anchor" href="#_4-the-reproduced-gap-is-much-narrower-than-an-incomplete-identity-system" aria-label="Permalink to &quot;4. The reproduced gap is much narrower than an incomplete identity system&quot;">​</a></h2><p>To decide whose permissions an action should use, we first need to know which instruction caused it. We therefore checked a more basic question: <strong>can the original instruction reference be followed all the way into the execution session?</strong> This is one part of responsibility tracing, not a test of human authorization.</p><p>Following the chat-continuation path revealed a placement difference. The message identifier reached the command, but <strong>it was saved when supplied at the outer level and absent from its session field when supplied inside continuation information.</strong></p><p>Specifically, the continuation command retained a chat reference and placed the triggering message identifier, <code>trigger_chat_id</code>, in continuation context. The dispatcher passed that nested context to the session manager. When persisting the triggering-message field, however, the session manager read only the top level.</p><p>This is a simplified field-location illustration, not an additional experiment:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>context.trigger_chat_id</span></span>
<span class="line"><span>    -&gt; session.runtime_trigger_chat_id is saved</span></span>
<span class="line"><span></span></span>
<span class="line"><span>context.continuation.trigger_chat_id</span></span>
<span class="line"><span>    -&gt; corresponding session field is not saved</span></span></code></pre></div><p>We placed the same source field at each location and called the actual session manager with an in-memory execution adapter instead of a real model.</p><table tabindex="0"><thead><tr><th>Input placement</th><th>Triggering message saved in session?</th><th>Logical execution ID also supplied: saved?</th></tr></thead><tbody><tr><td>Top-level context</td><td>Yes</td><td>Yes</td></tr><tr><td>Nested continuation context</td><td>No</td><td>Yes</td></tr></tbody></table><p><img src="`+d+'" alt="J1/J2 field projection: the nested triggering-message reference is absent, while both logical execution IDs are saved."></p><p><em>Figure 1. J1/J2. Absence concerns one session field, not the loss of all chat or command provenance. Source: <a href="/joinwell52/en/research/evidence/2026-09-08-principal-receipt">formal first-party observations and boundaries</a>.</em></p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/principal-receipt-20260908/01-source-projection.en.svg" target="_blank" rel="noreferrer">Open full-size figure</a></p><p>The entire session record had not failed to save: the logical execution ID supplied in the same call was persisted. The missing item was the triggering message ID. The code matches the observation: it searches both locations for the logical execution ID, but only the top level for the triggering message.</p><p>A separate isolated scenario started through the actual dispatcher also lacked the corresponding triggering-message field in its session record. The four identity probes produced consistent results in two formal runs.</p><p>The confirmed gap is therefore specific: <strong>source information reached the command, but was not projected through the designated session field.</strong></p><p>This relates to Paperclip&#39;s question without being the same problem. Chat and command evidence still retain references, so history has not disappeared. A message ID is not a human credential, so repairing this projection would not complete multi-person authorization.</p><p>Its practical value is that a query depending on this session field might see no source reference without knowing that the previous layer received one. That hop deserves an explanation before building a chain from an operation back to its instruction.</p><h2 id="_5-where-should-the-research-lead-rather-than-what-should-be-built-immediately" tabindex="-1">5. Where should the research lead, rather than what should be built immediately? <a class="header-anchor" href="#_5-where-should-the-research-lead-rather-than-what-should-be-built-immediately" aria-label="Permalink to &quot;5. Where should the research lead, rather than what should be built immediately?&quot;">​</a></h2><p>This research does not call for immediately rebuilding an identity platform. Retain existing agent-subject binding; review the source-reference handoff contract now; establish a separate requirement and authority boundary before adding shared credentials.</p><p>The triggering-message projection difference is a narrow engineering-review topic: who supplies it, which entrances use nested context, how conflicting top-level and nested values should be handled, and which queries actually depend on the field. Those need a clear read/write contract, not an identity platform inferred from one missing value.</p><p>Shared credentials need an actual product requirement first. If different people must direct the same digital employee over time, further questions include when instructions are accepted, how responsibility is authenticated, when an old action fixes its identity, how a new action selects authority, and what the underlying platform already supplies. This experiment neither implemented nor accepted that complete chain.</p><p>A useful check for agent-product teams is to select one real action and trace backward through its credential, authority, responsible person and original instruction. At the first hop that can only answer “probably this person,” clarify the evidence for that hop.</p><p><strong>Remembering who said what is not the same as knowing whose permissions each action may use. Session continuity keeps work connected; responsibility continuity keeps actions attributable.</strong></p><h2 id="research-and-evidence-boundaries" tabindex="-1">Research and evidence boundaries <a class="header-anchor" href="#research-and-evidence-boundaries" aria-label="Permalink to &quot;Research and evidence boundaries&quot;">​</a></h2><p>The first-party experiments used fixed source commit <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code> on Windows with Node v24.16.0. Approval tests used counting callbacks; session tests used an in-memory SDK, not real model tools. Task lookup and governance dependencies of the chat-command builder were synthetic. We did not test authentication or credential switching between two human accounts. These are bounded source and probe observations, not platform-wide security assurance or independent QA.</p><p><a href="/joinwell52/en/research/evidence/2026-09-08-principal-receipt">English evidence guide</a> · <a href="/joinwell52/zh/research/evidence/2026-09-08-principal-receipt">Chinese guide</a>. The public bundle contains sanitized observations, source hashes, aggregate historical counts and a record checker. It checks saved evidence, not a fresh product execution; original operational records and full product replay remain access-restricted. The historical sample did not contain the hypothetical multi-person credential incident. No product change or development authorization resulted from this research.</p>',53))])}const w=o(l,[["render",h]]);export{y as __pageData,w as default};
